def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            components.append((color, cells))

    objects = []
    for color, cells in components:
        if color != bg and len(cells) >= 2:
            rs = [r for r, c in cells]
            cs = [c for r, c in cells]
            objects.append((color, min(rs), max(rs), min(cs), max(cs)))

    out = [row[:] for row in grid]
    for color, cells in components:
        if color == bg or len(cells) != 1:
            continue
        r, c = cells[0]
        replacements = [
            obj for obj in objects
            if obj[1] <= r <= obj[2] and obj[3] <= c <= obj[4]
        ]
        if replacements:
            # Prefer the smallest enclosing object.
            obj = min(replacements, key=lambda o: (o[2] - o[1] + 1) * (o[4] - o[3] + 1))
            out[r][c] = obj[0]
        else:
            out[r][c] = bg

    return out
